def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The large uniform rectangular patches are the intended objects.
    # Recolor stray pixels inside a patch to its patch color; isolated
    # marks outside patches become the surrounding background.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (4, 7):
                continue

            # Look for a same-colored rectangular patch around the mark,
            # allowing the mark itself to be the interruption.
            candidates = []
            for color in set(x for row in grid for x in row):
                if color in (4, 7, 9):
                    continue
                for top in range(max(0, r-6), r+1):
                    for left in range(max(0, c-6), c+1):
                        for bottom in range(r, min(h, top+8)):
                            for right in range(c, min(w, left+8)):
                                if not (top <= r <= bottom and left <= c <= right):
                                    continue
                                cells = [(y, x) for y in range(top, bottom+1)
                                         for x in range(left, right+1)]
                                if len(cells) < 6:
                                    continue
                                if all(grid[y][x] == color or (y, x) == (r, c)
                                       for y, x in cells):
                                    candidates.append((len(cells), color))
            if candidates:
                out[r][c] = max(candidates)[1]
            else:
                out[r][c] = 9
    return out
